WITH filtered AS (SELECT *, TRIM(status) AS clean_status, DATE_SUB(end_date, 46) AS end_date_minus_46d FROM subscriptions WHERE end_date > '2025-06-20') SELECT *, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY end_date, id) AS event_seq, STDDEV_SAMP(monthly_fee) OVER (PARTITION BY plan) AS plan_stddev_samp_monthly_fee, LAST_VALUE(monthly_fee, TRUE) OVER (ORDER BY end_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_monthly_fee, FIRST_VALUE(monthly_fee) IGNORE NULLS OVER (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_monthly_fee, PERCENT_RANK() OVER (PARTITION BY customer_id ORDER BY monthly_fee DESC NULLS FIRST) AS monthly_fee_percent_rank FROM filtered
